<?php
require_once __DIR__.'/../includes/member.php';$user=require_login();if($user['role']==='admin')redirect('admin/dashboard.php');
$fines=rows("SELECT f.*,b.title,b.book_id FROM fines f LEFT JOIN borrowings br ON br.id=f.borrowing_id LEFT JOIN books b ON b.id=br.book_id WHERE f.user_id=? ORDER BY f.created_at DESC",[$user['id']]);
$total=(int)one("SELECT COALESCE(SUM(amount),0) amount FROM fines WHERE user_id=? AND status='unpaid'",[$user['id']])['amount'];member_start('Informasi Denda',$user,'peminjaman.php'); ?>
<section class="member-section"><span class="member-kicker">KEBIJAKAN PERPUSTAKAAN</span><h1>Denda &amp; Pembayaran</h1><div class="fine-rule-list"><article><b>Denda keterlambatan</b><p>Rp1.000 untuk setiap hari keterlambatan.</p></article><article><b>Pengingat pembayaran</b><p>Bookify menjadwalkan pengingat melalui email satu kali seminggu, paling lama dua bulan sejak denda tercatat.</p></article><article><b>Pembayaran denda</b><p>Pembayaran dilakukan langsung kepada admin perpustakaan. Saat membayar, anggota harus membawa buku yang sedang dipinjam.</p></article></div><p>Total denda belum lunas: <strong><?=rupiah($total)?></strong></p></section>
<section class="member-section"><h2>Rincian denda</h2><div class="member-table-wrap"><table><thead><tr><th>Buku</th><th>Hari terlambat</th><th>Jumlah</th><th>Status</th><th>Tanggal</th></tr></thead><tbody><?php foreach($fines as $fine):?><tr><td><?=e($fine['title']??'—')?> <small><?=e($fine['book_id']??'')?></small></td><td><?=(int)$fine['days_late']?></td><td><?=rupiah((int)$fine['amount'])?></td><td><?=status_badge($fine['status'])?></td><td><?=date_id($fine['created_at'])?></td></tr><?php endforeach;?><?php if(!$fines):?><tr><td colspan="5">Belum ada catatan denda.</td></tr><?php endif;?></tbody></table></div><p class="muted">Pembayaran dilakukan di perpustakaan; aplikasi ini tidak menerima pembayaran denda secara daring.</p></section><?php member_end(); ?>
